                  <th style={{ minWidth: '60px', padding: '6px', background: '#475569', color: 'white', fontWeight: 600 }}>TACC</th>
                  <th style={{ minWidth: '60px', padding: '6px', background: '#64748b', color: 'white', fontWeight: 600 }}>TSIN</th>
