'use client';

import { useState, useEffect, useMemo } from 'react';
import * as xlsx from 'xlsx';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

type Siniestro = {
  fechaPresentacion: string;
  tipoSiniestroIngreso: string;
  dp: string;
  estabBase: string;
};

type Homologacion = {
  estabBase: string;
  establecimiento: string;
  cantidadTrabajadores: number;
};

const meses = ['ENERO', 'FEBRERO', 'MARZO', 'ABRIL', 'MAYO', 'JUNIO', 'JULIO', 'AGOSTO', 'SEPTIEMBRE', 'OCTUBRE', 'NOVIEMBRE', 'DICIEMBRE'];

export default function EstadisticasClient({ isAdmin }: { isAdmin: boolean }) {
  const [data, setData] = useState<{ siniestros: Siniestro[], homologacion: Homologacion[] }>({ siniestros: [], homologacion: [] });
  const [loading, setLoading] = useState(true);
  const [anio, setAnio] = useState(new Date().getFullYear().toString());
  const [activeTab, setActiveTab] = useState('Accidente de Trabajo');
  const tabs = ['Accidente de Trabajo', 'Enfermedad Profesional', 'Accidente de Trayecto'];

  const fetchData = async () => {
    setLoading(true);
    const res = await fetch(`/api/estadisticas?anio=${anio}`);
    const json = await res.json();
    setData(json);
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
  }, [anio]);

  const groupedData = useMemo(() => {
    if (!data.homologacion) return [];
    const map = new Map();

    data.homologacion.forEach(h => {
      if (!map.has(h.estabBase)) {
        map.set(h.estabBase, {
          estabBase: h.estabBase,
          nombre: h.establecimiento,
          trabajadores: h.cantidadTrabajadores,
          meses: Array.from({ length: 12 }, () => ({ acc: 0, dp: 0 })),
          total: { acc: 0, dp: 0 }
        });
      }
    });

    const filtered = data.siniestros.filter(s => s.tipoSiniestroIngreso === activeTab);

    filtered.forEach(s => {
      const estab = map.get(s.estabBase);
      if (!estab) return;

      const parts = s.fechaPresentacion.split('-');
      if (parts.length >= 2) {
        const mIdx = parseInt(parts[1], 10) - 1;
        if (mIdx >= 0 && mIdx <= 11) {
          estab.meses[mIdx].acc += 1;
          const dpVal = parseInt(s.dp, 10);
          if (!isNaN(dpVal) && dpVal > 0) {
            estab.meses[mIdx].dp += dpVal;
          }

          estab.total.acc += 1;
          if (!isNaN(dpVal) && dpVal > 0) {
            estab.total.dp += dpVal;
          }
        }
      }
    });

    const result = Array.from(map.values()).map((estab: any) => {
      const calc = (acc: number, dp: number) => {
        const tacc = estab.trabajadores > 0 ? (acc / estab.trabajadores) : 0;
        const tsin = estab.trabajadores > 0 ? (dp * 100 / estab.trabajadores) : 0;
        return { tacc: tacc.toFixed(2), tsin: tsin.toFixed(2) };
      };

      const mesesCalculados = estab.meses.map((m: any) => ({ ...m, ...calc(m.acc, m.dp) }));
      const totalCalculado = { ...estab.total, ...calc(estab.total.acc, estab.total.dp) };

      return { ...estab, meses: mesesCalculados, total: totalCalculado };
    });

    return result.sort((a, b) => a.estabBase.localeCompare(b.estabBase));
  }, [data, activeTab]);

  const exportExcel = () => {
    if (groupedData.length === 0) return alert('No hay datos para exportar');

    const rows = groupedData.map(d => {
      const row: any = {
        'UNIDADES': d.estabBase,
        'NOMBRE': d.nombre,
        'N TRAB': d.trabajadores
      };

      d.meses.forEach((m: any, idx: number) => {
        const prefix = meses[idx];
        row[`${prefix} ACC`] = m.acc;
        row[`${prefix} DP`] = m.dp;
        row[`${prefix} TACC`] = Number(m.tacc);
        row[`${prefix} TSIN`] = Number(m.tsin);
      });

      row['TOTAL ACC'] = d.total.acc;
      row['TOTAL DP'] = d.total.dp;
      row['TOTAL TACC'] = Number(d.total.tacc);
      row['TOTAL TSIN'] = Number(d.total.tsin);

      return row;
    });

    const ws = xlsx.utils.json_to_sheet(rows);
    const wb = xlsx.utils.book_new();
    xlsx.utils.book_append_sheet(wb, ws, activeTab.substring(0, 31)); // excel tab names max 31 chars
    xlsx.writeFile(wb, `Estadisticas_${activeTab}_${anio}.xlsx`);
  };

  // Separar datos de gráficos entre Liceos y Escuelas
  const chartDataLiceos = useMemo(() => {
    return groupedData.filter(d => d.nombre.toLowerCase().includes('liceo') || d.estabBase.startsWith('A') || d.estabBase.startsWith('B'))
      .map(d => ({
        name: d.estabBase,
        TACC: Number(d.total.tacc),
        TSIN: Number(d.total.tsin)
      }));
  }, [groupedData]);

  const chartDataEscuelas = useMemo(() => {
    return groupedData.filter(d => d.nombre.toLowerCase().includes('escuela') || d.estabBase.startsWith('D') || d.estabBase.startsWith('E') || d.estabBase.startsWith('F'))
      .map(d => ({
        name: d.estabBase,
        TACC: Number(d.total.tacc),
        TSIN: Number(d.total.tsin)
      }));
  }, [groupedData]);

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '2rem', alignItems: 'flex-end' }}>
        <h1 style={{ fontSize: '2.5rem', fontWeight: 700, margin: 0 }}>Estadísticas Anuales</h1>
        <div style={{ display: 'flex', gap: '1rem', alignItems: 'flex-end' }}>
          <div>
            <label style={{ fontSize: '0.875rem', display: 'block', marginBottom: '0.5rem', color: 'var(--text-secondary)' }}>Año a Consultar</label>
            <input type="number" className="input-field" value={anio} onChange={e => setAnio(e.target.value)} style={{ width: '120px' }} />
          </div>
          <button onClick={exportExcel} className="btn btn-primary">Exportar Tabla a Excel</button>
        </div>
      </div>

      <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '2rem', flexWrap: 'wrap' }}>
        {tabs.map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            style={{
              padding: '10px 20px',
              borderRadius: '8px',
              border: activeTab === tab ? 'none' : '1px solid var(--border-color)',
              cursor: 'pointer',
              fontWeight: 600,
              transition: 'all 0.2s',
              background: activeTab === tab ? 'var(--primary-color)' : 'white',
              color: activeTab === tab ? 'white' : 'var(--text-primary)',
              boxShadow: activeTab === tab ? '0 4px 10px rgba(1,96,152,0.3)' : 'none'
            }}
          >
            {tab}
          </button>
        ))}
      </div>

      {loading ? (
        <div style={{ padding: '4rem', textAlign: 'center', color: 'var(--text-secondary)' }}>Cargando matriz anual...</div>
      ) : (
        <>
          {/* Gráficos */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '2rem', marginBottom: '3rem' }}>
            <div className="glass-panel" style={{ padding: '1.5rem' }}>
              <h3 style={{ marginBottom: '1.5rem', color: 'var(--primary-color)' }}>Indicadores Accidentabilidad (TACC) - Liceos</h3>
              <div style={{ height: 300 }}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartDataLiceos}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                    <XAxis dataKey="name" tick={{ fontSize: 11 }} interval={0} angle={-45} textAnchor="end" />
                    <YAxis />
                    <Tooltip contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 15px rgba(0,0,0,0.1)' }} />
                    <Legend wrapperStyle={{ paddingTop: '20px' }} />
                    <Bar dataKey="TACC" fill="#F7A517" name="Tasa de Accidentabilidad" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>

            <div className="glass-panel" style={{ padding: '1.5rem' }}>
              <h3 style={{ marginBottom: '1.5rem', color: 'var(--primary-color)' }}>Indicadores Siniestralidad (TSIN) - Liceos</h3>
              <div style={{ height: 300 }}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartDataLiceos}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                    <XAxis dataKey="name" tick={{ fontSize: 11 }} interval={0} angle={-45} textAnchor="end" />
                    <YAxis />
                    <Tooltip contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 15px rgba(0,0,0,0.1)' }} />
                    <Legend wrapperStyle={{ paddingTop: '20px' }} />
                    <Bar dataKey="TSIN" fill="#EB567F" name="Tasa de Siniestralidad" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>

            <div className="glass-panel" style={{ padding: '1.5rem' }}>
              <h3 style={{ marginBottom: '1.5rem', color: 'var(--primary-color)' }}>Indicadores Accidentabilidad (TACC) - Escuelas</h3>
              <div style={{ height: 300 }}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartDataEscuelas}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                    <XAxis dataKey="name" tick={{ fontSize: 11 }} interval={0} angle={-45} textAnchor="end" />
                    <YAxis />
                    <Tooltip contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 15px rgba(0,0,0,0.1)' }} />
                    <Legend wrapperStyle={{ paddingTop: '20px' }} />
                    <Bar dataKey="TACC" fill="#39BABD" name="Tasa de Accidentabilidad" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>

            <div className="glass-panel" style={{ padding: '1.5rem' }}>
              <h3 style={{ marginBottom: '1.5rem', color: 'var(--primary-color)' }}>Indicadores Siniestralidad (TSIN) - Escuelas</h3>
              <div style={{ height: 300 }}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartDataEscuelas}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                    <XAxis dataKey="name" tick={{ fontSize: 11 }} interval={0} angle={-45} textAnchor="end" />
                    <YAxis />
                    <Tooltip contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 15px rgba(0,0,0,0.1)' }} />
                    <Legend wrapperStyle={{ paddingTop: '20px' }} />
                    <Bar dataKey="TSIN" fill="#016098" name="Tasa de Siniestralidad" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>
          </div>

          {/* Mega-Tabla */}
          <div className="glass-panel" style={{ padding: '1.5rem', overflowX: 'auto' }}>
            <h3 style={{ marginBottom: '1rem', color: 'var(--primary-color)' }}>Matriz de Datos: {activeTab}</h3>
            <table style={{ minWidth: '2500px', fontSize: '0.8rem' }}>
              <thead>
                <tr>
                  <th rowSpan={2} style={{ background: '#f8fafc', position: 'sticky', left: 0, zIndex: 2, minWidth: '80px' }}>Unidad</th>
                  <th rowSpan={2} style={{ background: '#f8fafc', position: 'sticky', left: '80px', zIndex: 2, minWidth: '250px' }}>Nombre</th>
                  <th rowSpan={2} style={{ background: '#f8fafc', borderRight: '2px solid #cbd5e1' }}>N° Trab</th>

                  {meses.map(m => (
                    <th key={m} colSpan={4} style={{ textAlign: 'center', borderRight: '1px solid #cbd5e1', borderBottom: '1px solid var(--border-color)', background: 'var(--primary-color)', color: 'white' }}>{m}</th>
                  ))}
                  <th colSpan={4} style={{ textAlign: 'center', background: '#0f172a', color: 'white' }}>TOTAL AÑO</th>
                </tr>
                <tr>
                  {meses.map(m => (
                    <td key={`sub-${m}`} style={{ padding: 0 }}>
                      <table style={{ width: '100%', tableLayout: 'fixed' }}>
                        <tbody>
                          <tr>
                            <td style={{ width: '25%', padding: '8px 4px', textAlign: 'center', background: '#e0f2fe', color: '#0369a1', fontWeight: 600, border: 'none' }}>ACC</td>
                            <td style={{ width: '25%', padding: '8px 4px', textAlign: 'center', background: '#fef08a', color: '#854d0e', fontWeight: 600, border: 'none' }}>DP</td>
                            <td style={{ width: '25%', padding: '8px 4px', textAlign: 'center', background: '#fce7f3', color: '#be185d', fontWeight: 600, border: 'none' }}>TACC</td>
                            <td style={{ width: '25%', padding: '8px 4px', textAlign: 'center', background: '#dcfce7', color: '#166534', fontWeight: 600, borderRight: '1px solid #cbd5e1' }}>TSIN</td>
                          </tr>
                        </tbody>
                      </table>
                    </td>
                  ))}
                  <td style={{ padding: 0 }}>
                      <table style={{ width: '100%', tableLayout: 'fixed' }}>
                        <tbody>
                          <tr>
                            <td style={{ width: '25%', padding: '8px 4px', textAlign: 'center', background: '#1e293b', color: 'white', fontWeight: 600, border: 'none' }}>ACC</td>
                            <td style={{ width: '25%', padding: '8px 4px', textAlign: 'center', background: '#334155', color: 'white', fontWeight: 600, border: 'none' }}>DP</td>
                            <td style={{ width: '25%', padding: '8px 4px', textAlign: 'center', background: '#475569', color: 'white', fontWeight: 600, border: 'none' }}>TACC</td>
                            <td style={{ width: '25%', padding: '8px 4px', textAlign: 'center', background: '#64748b', color: 'white', fontWeight: 600, border: 'none' }}>TSIN</td>
                          </tr>
                        </tbody>
                      </table>
                    </td>
                </tr>
              </thead>
              <tbody>
                {groupedData.map(d => (
                  <tr key={d.estabBase}>
                    <td style={{ background: 'white', position: 'sticky', left: 0, zIndex: 1, fontWeight: 'bold' }}>{d.estabBase}</td>
                    <td style={{ background: 'white', position: 'sticky', left: '80px', zIndex: 1 }}>{d.nombre}</td>
                    <td style={{ textAlign: 'center', borderRight: '2px solid #cbd5e1', fontWeight: 'bold' }}>{d.trabajadores}</td>

                    {d.meses.map((m: any, idx: number) => (
                      <td key={idx} style={{ padding: 0, borderRight: '1px solid #cbd5e1' }}>
                        <table style={{ width: '100%', tableLayout: 'fixed' }}>
                          <tbody>
                            <tr>
                              <td style={{ width: '25%', padding: '12px 4px', textAlign: 'center', border: 'none' }}>{m.acc}</td>
                              <td style={{ width: '25%', padding: '12px 4px', textAlign: 'center', border: 'none' }}>{m.dp}</td>
                              <td style={{ width: '25%', padding: '12px 4px', textAlign: 'center', border: 'none' }}>{m.tacc}</td>
                              <td style={{ width: '25%', padding: '12px 4px', textAlign: 'center', border: 'none' }}>{m.tsin}</td>
                            </tr>
                          </tbody>
                        </table>
                      </td>
                    ))}

                    <td style={{ padding: 0, background: '#f8fafc', fontWeight: 'bold' }}>
                      <table style={{ width: '100%', tableLayout: 'fixed' }}>
                        <tbody>
                          <tr>
                            <td style={{ width: '25%', padding: '12px 4px', textAlign: 'center', border: 'none', color: '#0369a1' }}>{d.total.acc}</td>
                            <td style={{ width: '25%', padding: '12px 4px', textAlign: 'center', border: 'none', color: '#854d0e' }}>{d.total.dp}</td>
                            <td style={{ width: '25%', padding: '12px 4px', textAlign: 'center', border: 'none', color: '#be185d' }}>{d.total.tacc}</td>
                            <td style={{ width: '25%', padding: '12px 4px', textAlign: 'center', border: 'none', color: '#166534' }}>{d.total.tsin}</td>
                          </tr>
                        </tbody>
                      </table>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}
    </div>
  );
}

